test("bridge storage codec preserves scalar keys and rejects malformed representations",()=>{
 const source={challengeBridge:{activeOccurrence:"حدث😀",selectedCellId:"cell-0-0",applied:{["حدث😀\0cell-0-0"]:"award",["\ufeffé\0cell-1-0"]:"continue",["e\u0301\0cell-2-0"]:"award",["literal\\u0000\0cell-3-0"]:"continue"}}} as unknown as CanonicalRoom;
 const encoded=encodeStoredRoom(source),decoded=decodeStoredRoom(encoded);
 assert.equal(encoded.challengeBridge?.appliedEncoding,"utf8-hex-v1");assert.deepEqual({...decoded.challengeBridge?.applied},{...source.challengeBridge?.applied});assert.equal(Object.hasOwn(source.challengeBridge!,"appliedEncoding"),false);
 assert.throws(()=>encodeStoredRoom(encoded as unknown as CanonicalRoom));
 for(const key of ["missing-delimiter","a\0b\0c","\ud800\0cell-0-0","\0cell-0-0"]) assert.throws(()=>encodeStoredRoom({challengeBridge:{activeOccurrence:"a",selectedCellId:"cell-0-0",applied:{[key]:"award"}}} as unknown as CanonicalRoom));
 assert.throws(()=>encodeStoredRoom({challengeBridge:{activeOccurrence:"\ud800",selectedCellId:"cell-0-0",applied:{}}} as unknown as CanonicalRoom));
 const base=encoded.challengeBridge!;for(const key of ["ABC0","0","zz","c0800063","0063"]) assert.throws(()=>decodeStoredRoom({challengeBridge:{...base,applied:{[key]:"award"}}}));
 assert.throws(()=>decodeStoredRoom({challengeBridge:{...base,appliedEncoding:"unknown"}}));assert.throws(()=>decodeStoredRoom({challengeBridge:{activeOccurrence:"a",selectedCellId:"cell-0-0",applied:{"a\\u0000cell":"award"}}}));
 const empty={challengeBridge:{activeOccurrence:"a",selectedCellId:"cell-0-0",applied:{}}};assert.equal(Object.hasOwn(decodeStoredRoom(empty).challengeBridge!,"appliedEncoding"),false);assert.equal(encodeStoredRoom(decodeStoredRoom(empty)).challengeBridge?.appliedEncoding,"utf8-hex-v1");
 assert.throws(()=>decodeStoredRoom({challengeBridge:null}));
 const accessor=Object.defineProperty({},"a\0cell-0-0",{enumerable:true,get:()=>"award"});assert.throws(()=>encodeStoredRoom({challengeBridge:{activeOccurrence:"a",selectedCellId:"cell-0-0",applied:accessor}} as unknown as CanonicalRoom));
 const symbols={};Object.defineProperty(symbols,Symbol("hidden"),{value:"award"});assert.throws(()=>encodeStoredRoom({challengeBridge:{activeOccurrence:"a",selectedCellId:"cell-0-0",applied:symbols}} as unknown as CanonicalRoom));
 const restored=decodeStoredRoom(encodeStoredRoom({challengeBridge:{activeOccurrence:"a",selectedCellId:"cell-0-0",applied:{["a\0cell-0-0"]:"award"}}} as unknown as CanonicalRoom)).challengeBridge!;
 const game=initialGameState(),challenge={occurrence:"a",result:"correct",attemptsClosed:true,awarded:false} as never;
 assert.equal(applyChallengeAward(challenge,game,restored).game,game);assert.equal(applyChallengeContinuation(challenge,game,restored).game,game);
});
