 await commands.commitCommand(context,snapshot,intent,room,member,undefined,intent.type,false,undefined,[member],[]);await commands.commitExpiry(context,snapshot,room,[]);await commands.commitChallengeExpiry(context,snapshot,{type:"SERVER_CHALLENGE_DEADLINE",intentId:":challenge-expiry:"+hash,expectedRevision:1,payload:{occurrence:"occurrence",challengeRevision:1,stage:"answer",observedDeadlineMs:1}},room,[]);
 const lobby=postgresLobbyRepository(io),loaded=await lobby.loadLobby(context,"room",1),joined=await lobby.loadJoinLobby(context,"room",1);assert.equal(loaded.stateHash,hash);assert.equal(joined.stateHash,hash);assert.deepEqual({...loaded.state.room.challengeBridge?.applied},{...room.challengeBridge?.applied});
 await lobby.commitLobby(context,loaded,intent,state);await lobby.createLobby(context,{type:"CREATE_ROOM",intentId:"new",displayName:"Host",config:room.config},state);
 const paid=postgresPaidRepository(io),paidLobby=await paid.loadLobby(context,"room",1);assert.equal(paidLobby.stateHash,hash);
